function updateCelebrationCountdown(){const remaining=Math.max(0,Math.floor((new Date('2026-11-27T00:00:00+05:30').getTime()-Date.now())/1000));const values={days:Math.floor(remaining/86400),hours:Math.floor(remaining/3600)%24,minutes:Math.floor(remaining/60)%60,seconds:remaining%60};for(const [key,value] of Object.entries(values))document.querySelector(`[data-count="${key}"]`).textContent=String(value).padStart(2,'0')}updateCelebrationCountdown();setInterval(updateCelebrationCountdown,1000);document.querySelectorAll('.invitation-block:not(.shown)').forEach(el=>revealSections.observe(el));
